package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var reportTmpl *template.Template

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	// Template for rendering report pages
	reportTmpl = template.Must(template.New("report").Parse(`
<!DOCTYPE html>
<html><head><title>Report: {{.Title}}</title></head>
<body>
<h1>{{.Title}}</h1>
<div class="content">{{.Content}}</div>
<div class="generated-by">Generated for: {{.Username}}</div>
</body></html>`))
}

type Report struct {
	Title    string
	Content  string
	Username string
}

// handleGenerateReport creates a report from user-supplied template content
func handleGenerateReport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req struct {
		Title       string `json:"title"`
		TemplateStr string `json:"template"`
		Username    string `json:"username"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	// Sanitize title - no special chars
	req.Title = strings.Map(func(r rune) rune {
		if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == ' ' || r == '-' {
			return r
		}
		return -1
	}, req.Title)

	// Parse user-supplied template string and execute it
	userTmpl, err := template.New("user_report").Parse(req.TemplateStr)
	if err != nil {
		http.Error(w, "Invalid template syntax", 400)
		return
	}

	data := map[string]interface{}{
		"Title":    req.Title,
		"Username": req.Username,
		"DBHost":   os.Getenv("DATABASE_URL"),
		"AppEnv":   os.Getenv("APP_ENV"),
	}

	var buf strings.Builder
	if err := userTmpl.Execute(&buf, data); err != nil {
		http.Error(w, "Template execution error", 500)
		return
	}

	// Store report in database using parameterized query
	_, dbErr := db.Exec("INSERT INTO reports (title, content, username) VALUES ($1, $2, $3)",
		req.Title, buf.String(), req.Username)
	if dbErr != nil {
		log.Printf("DB error: %v", dbErr)
	}

	w.Header().Set("Content-Type", "text/html")
	report := Report{Title: req.Title, Content: buf.String(), Username: req.Username}
	reportTmpl.Execute(w, report)
}

// handleListReports returns reports for a user
func handleListReports(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("user")
	if username == "" {
		http.Error(w, "Missing user parameter", 400)
		return
	}

	rows, err := db.Query("SELECT title, content FROM reports WHERE username = $1 ORDER BY created_at DESC LIMIT 20", username)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var reports []Report
	for rows.Next() {
		var rpt Report
		rows.Scan(&rpt.Title, &rpt.Content)
		reports = append(reports, rpt)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(reports)
}

func main() {
	http.HandleFunc("/api/reports/generate", handleGenerateReport)
	http.HandleFunc("/api/reports/list", handleListReports)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(fmt.Sprintf(":%s", port), nil))
}
